        "ja": "\u5E38\u306B\u5F31\u706B\u3067\u8868\u9762\u304C\u63FA\u308C\u308B\u7A0B\u5EA6\u306E\u706B\u52A0\u6E1B\u3092\u4FDD\u3061\u3001\u30D5\u30BF\u306F\u305A\u3089\u3057\u3066\u304A\u304D\u307E\u3059\u3002\u6FC1\u3063\u3066\u3057\u307E\u3063\u305F\u3089\u5375\u767D2\u500B\u5206\u3092\u5165\u308C\u3066\u5F31\u706B\u306B\u304B\u3051\u308B\u3068\u3001\u30A2\u30AF\u3092\u5438\u7740\u3057\u3066\u6F84\u3093\u3060\u72B6\u614B\u306B\u623B\u305B\u307E\u3059\u3002",
