        "zh-TW": "\u5E73\u5E95\u934B\u5012\u5165\u5C11\u8A31\u6CB9\u5927\u706B\u71D2\u71B1\uFF0C\u5C07\u9183\u597D\u7684\u8C6C\u8089\u7247\u55AE\u5C64\u92EA\u958B\u3002\u5927\u706B\u6BCF\u9762\u5404\u714E 2 \u5206\u9418\uFF0C\u76F4\u5230\u908A\u7DE3\u5448\u73FE\u871C\u6C41\u7126\u9999\u91D1\u9EC3\u8272\uFF08\u944A\u6C23\u6EFF\u6EFF\uFF09\uFF0C\u76DB\u51FA\u5099\u7528\u3002",
