        "ja": "\u3054\u98EF\u304C\u30D9\u30C1\u30E3\u3064\u3044\u3066\u56E3\u5B50\u72B6\u306B\u306A\u3063\u3066\u3057\u307E\u3063\u305F",
        "ko": "\uBC25\uC774 \uC9C8\uCC99\uAC70\uB9AC\uACE0 \uB5A1\uCC98\uB7FC \uBB49\uCCD0\uBC84\uB838\uC5B4\uC694"
