        "ja": "\u6C34\u304C\u591A\u3059\u304E\u305F\u304B\u3001\u708A\u304F\u524D\u306B\u9577\u304F\u6D78\u6C34\u3055\u305B\u3066\u3057\u307E\u3063\u305F\u3002",
        "ko": "\uBB3C\uC744 \uB108\uBB34 \uB9CE\uC774 \uB123\uC5C8\uAC70\uB098 \uC300\uC744 \uBBF8\uB9AC \uBD88\uB824\uB450\uC5C8\uAE30 \uB54C\uBB38\uC785\uB2C8\uB2E4."
