      "ja": "\u81F3\u798F\u306E\u98DF\u3079\u65B9\uFF1A\u534A\u719F\u76EE\u7389\u713C\u304D\u306E\u9EC4\u8EAB\u3092\u5272\u308A\u3001\u30A2\u30C4\u30A2\u30C4\u306E\u3054\u98EF\u3068\u30CD\u30AE\u6CB9\u306E\u4E0A\u306B\u30C8\u30ED\u30EA\u3068\u7D61\u307E\u305B\u307E\u3059\u3002\u7518\u9178\u3063\u3071\u3044\u30BF\u30EC\u3092\u304B\u3051\u3066\u4E00\u7DD2\u306B\u982C\u5F35\u308B\u306E\u304C\u672C\u5834\u30B5\u30A4\u30B4\u30F3\u306E\u918D\u9190\u5473\uFF01",
      "ko": "\uD604\uC9C0\uC778 \uBA39\uBC29 \uD301: \uBC18\uC219 \uB178\uB978\uC790\uB97C \uD1A1 \uD130\uB728\uB824 \uACE0\uC2AC\uACE0\uC2AC\uD55C \uBC25\uACFC \uD30C\uAE30\uB984 \uC704\uC5D0 \uD750\uB974\uAC8C \uD55C \uB4A4, \uB291\uCC38 \uC18C\uC2A4\uB97C \uC0B4\uC9DD \uBFCC\uB824 \uBE44\uBCBC \uB4DC\uC154\uBCF4\uC138\uC694!"
