        "ja": "\u304D\u3064\u304F\u5DFB\u304D\u3059\u304E\u306A\u3044\u3053\u3068\uFF01\u52A0\u71B1\u3067\u9921\u304C\u81A8\u3089\u3080\u305F\u3081\u3001\u3042\u308B\u7A0B\u5EA6\u306E\u904A\u3073\u3092\u6301\u305F\u305B\u3066\u5DFB\u304F\u306E\u304C\u30B3\u30C4\u3067\u3059\u3002",
