        "ja": "\u30B9\u30FC\u30D7\u304C\u6CB8\u9A30\u3057\u3066\u3044\u306A\u3044\u6BB5\u968E\u3067\u9B5A\u3092\u6295\u5165\u3057\u305F\u304B\u3001\u304A\u7389\u3067\u6FC0\u3057\u304F\u304B\u304D\u6DF7\u305C\u305F\u3002",
