        "ja": "\u30C8\u30F3\u30B0\u3067\u30D1\u30BF\u30F3\u3068\u534A\u5206\u306B\u6298\u308A\u305F\u305F\u307F\u307E\u3059\u300230\u79D2\u51B7\u307E\u3059\u3068\u30D1\u30EA\u30D1\u30EA\u611F\u304C\u30DE\u30C3\u30AF\u30B9\u306B\uFF01\u624B\u3067\u6301\u3063\u3066\u8C6A\u5FEB\u306B\u304B\u3076\u308A\u3064\u3051\u3070\u3001\u30D1\u30EA\u30C3\u3068\u5F3E\u3051\u308B\u76AE\u306E\u4E2D\u304B\u3089\u3068\u308D\u3051\u308B\u30C1\u30FC\u30BA\u3068\u30A8\u30D3\u306E\u65E8\u5473\u304C\u6EA2\u308C\u51FA\u3057\u307E\u3059\uFF01",
        "ko": "\uC9D1\uAC8C\uB85C \uBC18\uC744 \uD0C0\uCF54\uCC98\uB7FC \uC811\uC2B5\uB2C8\uB2E4. 30\uCD08 \uC815\uB3C4 \uD55C \uAE40 \uC2DD\uD788\uBA74 \uBC14\uC0AD\uD568\uC774 \uCD5C\uACE0\uC870\uC5D0 \uB2EC\uD569\uB2C8\uB2E4. \uC190\uC73C\uB85C \uB4E4\uACE0 \uD55C \uC785 \uBCA0\uC5B4 \uBB3C\uBA74 \uBC14\uC0AC\uC0AD \uBD80\uC11C\uC9C0\uB294 \uC18C\uB9AC\uC640 \uD568\uAED8 \uCE58\uC988\uC640 \uAC74\uC0C8\uC6B0\uC758 \uD48D\uBBF8\uAC00 \uC785\uC548 \uAC00\uB4DD \uBC88\uC9D1\uB2C8\uB2E4!"
