        "ja": "\u5E95\u306E\u30E9\u30A4\u30B9\u30DA\u30FC\u30D1\u30FC\u304C\u771F\u3063\u9ED2\u306B\u7126\u3052\u305F\u306E\u306B\u3001\u4E0A\u306E\u5375\u304C\u751F\u306E\u307E\u307E",
