        "ja": "\u30E9\u30A4\u30B9\u30DA\u30FC\u30D1\u30FC\u30922cm\u89D2\u306B\u5207\u308A\u3001\u6CB9\u306710\u79D2\u30B5\u30C3\u3068\u63DA\u3052\u3066\u30AF\u30EB\u30C8\u30F3\u72B6\u306B\u3057\u307E\u3059\u3002\u9EBA\u306F\u71B1\u6E6F\u30671\u5206\u30B5\u30C3\u3068\u6E6F\u901A\u3057\u3057\u3001\u72EC\u81EA\u306E\u529B\u5F37\u3044\u30B3\u30B7\u3092\u6B8B\u3057\u307E\u3059\u3002",
        "ko": "\uB77C\uC774\uC2A4\uD398\uC774\uD37C\uB97C \uC791\uAC8C \uC798\uB77C 180\xB0C \uAE30\uB984\uC5D0 10\uCD08\uAC04 \uBC14\uC0AD\uD558\uAC8C \uD280\uACA8\uB0C5\uB2C8\uB2E4. \uBA74\uC740 \uB053\uB294 \uBB3C\uC5D0 \uB531 1\uBD84\uAC04 \uC0B4\uC9DD \uB370\uCCD0 \uD2B9\uC720\uC758 \uCAC4\uAE43\uD55C \uC2DD\uAC10\uC744 \uC0B4\uB9BD\uB2C8\uB2E4."
